SELECT shop_id, shop_group_id, name
FROM shop
WHERE user_id = #{userId} AND shop_id = #{shopId}

SELECT shop_id, shop_group_id, name
FROM shop
WHERE user_id = #{userId} AND shop_group_id = #{shopGroupId} AND name = #{name}

SELECT COUNT(*)
FROM shop
WHERE user_id = #{userId} AND shop_group_id = #{shopGroupId}

SELECT COUNT(DISTINCT figure_id)
FROM figure
WHERE user_id = #{userId} AND shop_id = #{shopId}
